/**
 * Hand-written, neutral background on institutions and terms that recur in
 * German and European news. Every entry is a stable, checkable fact about what
 * something *is* — never a characterisation of a current event.
 *
 * This is the honest half of "why it matters": a student meeting "Sondervermögen"
 * or "Bundesverfassungsgericht" for the first time gets a real explanation,
 * generated by nobody and requiring no caveat.
 */
export interface GlossaryEntry {
  id: string;
  /** Surface forms that trigger the entry, folded before matching. */
  match: string[];
  term: { de: string; en: string };
  body: { de: string; en: string };
}

