/** Prebuilt lookup: folded surface form to entry. */
const BY_TOKEN = new Map<string, GlossaryEntry>();
for (const entry of GLOSSARY) {
  for (const form of entry.match) BY_TOKEN.set(fold(form), entry);
}

/**
 * Finds glossary entries relevant to a story. Matching runs over the clustering
 * tokens rather than raw text, so it benefits from the same alias bridge: a
 * German article saying "EZB" and an English one saying "ECB" both resolve here.
 */
export function findGlossary(tokens: string[], limit = 3): GlossaryEntry[] {
  const seen = new Set<string>();
  const out: GlossaryEntry[] = [];
  for (const token of tokens) {
    const entry = BY_TOKEN.get(token);
    if (entry && !seen.has(entry.id)) {
      seen.add(entry.id);
      out.push(entry);
      if (out.length >= limit) break;
    }
  }
  return out;
}
